import csv,re,unicodedata
from pathlib import Path

def norm(s):
 s=unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower()
 s=re.sub(r'\\b(jr|sr|ii|iii|iv)\\b','',s)
 s=re.sub(r'\\(["'^)]*'"\\)|\"["'^"]*"'"','',s)
 s=re.sub(r'\\b(bo|pete)\\b','',s)
 return re.sub(r'["'^a-z0-9]'"','',s)
with open('stage1/cohort.csv',newline='',encoding='utf-8') as f: ours=list(csv.DictReader(f))
with open('stage3/reference/derived_cohorts/cohorts/all_astronauts.tsv',newline='',encoding='utf-8') as f: ref=list(csv.DictReader(f,delimiter='\\t'))
print('ours',len(ours),'ref',len(ref))
O={norm(r['full_name']):r for r in ours}; R={norm(r['Name']):r for r in ref}
print('norm duplicates ours',len(ours)-len(O),'ref',len(ref)-len(R))
print('\\nONLY OURS')
for k in sorted(O.keys()-R.keys()):
 r=O[k]; print(r['person_id'],r['full_name'],'apollo',r['apollo_flew'],'core',r['core_nasa_non_apollo'],'x15',r['military_x15'],'dyna',r['military_dyna_soar'],'mol',r['military_mol'])
print('\\nONLY REF')
for k in sorted(R.keys()-O.keys()):
 r=R[k]; print(r['Name'],r['analysis_primary'],r['analysis_source_key'],r['Date of Birth'],r['Date of Death'])
print('\\nSHARED DATE/PRIMARY CONFLICTS')
for k in sorted(O.keys()&R.keys()):
 o,r=O[k],R[k]
 vals=[]
 if o['birth_date']"'!=r['"'Date of Birth']: vals.append(('birth',o['birth_date'],r['Date of Birth']))
 if o['death_date']"'!=r['"'Date of Death']: vals.append(('death',o['death_date'],r['Date of Death']))
 if (o['apollo_flew']=='1') "'!= (r['"'analysis_primary']=='apollo'): vals.append(('apollo',o['apollo_flew'],r['analysis_primary']))
 if vals: print(o['person_id'],o['full_name'],r['Name'],vals)
