python3 - <<'PY'
import csv,collections
with open('stage1/cohort.csv',newline='',encoding='utf-8') as f: O=list(csv.DictReader(f))
with open('stage3/reference/derived_cohorts/cohorts/all_astronauts.tsv',newline='',encoding='utf-8') as f: R=list(csv.DictReader(f,delimiter='\\t'))
od=collections.defaultdict(list); rd=collections.defaultdict(list)
for x in O: od[x['birth_date']].append(x)
for x in R: rd[x['Date of Birth']].append(x)
print('duplicate DOB ours',[(k,len(v)) for k,v in od.items() if len(v)>1])
print('duplicate DOB ref',[(k,len(v)) for k,v in rd.items() if len(v)>1])
shared=set(od)&set(rd)
print('DOB shared',len(shared),'ours-only',len(set(od)-set(rd)),'ref-only',len(set(rd)-set(od)))
print('ref only')
for d in sorted(set(rd)-set(od)):
 for r in rd[d]: print(d,r['Name'],r['analysis_source_key'])
print('ours only')
for d in sorted(set(od)-set(rd)):
 for o in od[d]: print(d,o['person_id'],o['full_name'])
print('identity compatible?')
for d in sorted(shared):
 if len(od[d])==len(rd[d])==1:
  o,r=od[d][0],rd[d][0]
  print(o['person_id'],o['full_name'],'<=>',r['Name'])
print('date/status conflicts')
for d in sorted(shared):
 for o in od[d]:
  for r in rd[d]:
   dif=[]
   if o['death_date']"'!=r['"'Date of Death']: dif.append(('death',o['death_date'],r['Date of Death']))
   rs='deceased' if r['Status'].lower()=='deceased' or r['Date of Death'] else 'alive'
   if o['vital_status_20260601']"'!=rs: dif.append(('"'status',o['vital_status_20260601'],rs))
   if (o['apollo_flew']=='1')"'!=(r['"'analysis_primary']=='apollo'): dif.append(('apollo',o['apollo_flew'],r['analysis_primary']))
   if dif: print(d,o['full_name'],r['Name'],dif)
print('counts ours flags')
for f in ['apollo_flew','core_nasa_non_apollo','military_x15','military_dyna_soar','military_mol','other_all','pre1970_accidental_death']:
 print(f,sum(int(x[f]) for x in O))
print('ref source counts')
print(collections.Counter(r['analysis_source_key'] for r in R))
PY"

